// 01. Normalización de campos del correo entrante (Outlook / Gmail / Directo)
const items = $input.all();
const normalized = [];

for (const item of items) {
  const data = item.json.body || item.json;

  const senderEmail = (data.sender_email || data.from || '').toLowerCase().trim();
  const senderName = data.sender_name || (data.from && data.from.includes('<') ? data.from.split('<')[0].replace(/['"]/g, '').trim() : '') || 'Coder';
  const subject = data.email_subject || data.subject || 'Sin asunto';
  const body = data.email_body || data.body || data.text || data.snippet || '';
  const messageId = data.message_id || data.id || 'msg_' + Date.now() + '_' + Math.random().toString(36).substring(2, 9);
  const conversationId = data.conversation_id || data.threadId || null;
  const receivedAt = data.received_at || data.date || new Date().toISOString();

  // Procesamiento de adjuntos
  const rawAttachments = data.attachments || [];
  const attachments = Array.isArray(rawAttachments) ? rawAttachments.map(att => ({
    filename: att.filename || att.name || 'documento.pdf',
    mime_type: att.mime_type || att.contentType || 'application/pdf',
    size_bytes: att.size || (att.data_base64 ? Math.round(att.data_base64.length * 0.75) : 0),
    data_base64: att.data_base64 || att.base64 || null
  })) : [];

  normalized.push({
    json: {
      source_provider: data.source_provider || (data.threadId ? 'GMAIL' : 'OUTLOOK'),
      message_id: messageId,
      conversation_id: conversationId,
      sender_email: senderEmail,
      sender_name: senderName,
      email_subject: subject,
      email_body: body,
      received_at: receivedAt,
      attachments: attachments,
      has_attachments: attachments.length > 0
    }
  });
}

return normalized;

// 02. Construcción de Deep Link y extracción heurística de Cédula/Nombre
const items = $input.all();

for (const item of items) {
  const d = item.json;

  // 1. Construir email_url para el panel HSE
  let emailUrl = '';
  if (d.source_provider === 'GMAIL') {
    emailUrl = `https://mail.google.com/mail/u/0/#search/rfc822msgid%3A${encodeURIComponent(d.message_id)}`;
  } else {
    // Outlook Web Deep Link
    emailUrl = `https://outlook.office.com/mail/deeplink/read/${encodeURIComponent(d.message_id)}`;
  }
  d.email_url = emailUrl;

  // 2. Extraer posible cédula del asunto o cuerpo (patrón 7 a 10 dígitos)
  const fullText = (d.email_subject + ' ' + d.email_body);
  const cedulaMatch = fullText.match(/\b(1\d{9}|[1-9]\d{6,8})\b/);
  d.search_cedula = cedulaMatch ? cedulaMatch[0] : '';

  // 3. Clave de búsqueda por nombre
  d.search_name = d.sender_name && d.sender_name !== 'Coder' ? d.sender_name.trim() : '';
}

return items;

// 04. Combinar metadatos del correo con el resultado de búsqueda del coder
const dbResult = $input.first()?.json || {};
const emailData = $('02 Extraer Claves e URL').first().json;

const coderFound = Boolean(dbResult.coder_id);

return [{
  json: {
    ...emailData,
    coder_found: coderFound,
    coder_id: coderFound ? dbResult.coder_id : null,
    coder_name: coderFound ? dbResult.coder_full_name : emailData.sender_name,
    coder_cedula: coderFound ? dbResult.coder_cedula : emailData.search_cedula,
    coder_route: coderFound ? dbResult.coder_route : null,
    coder_identification_status: coderFound ? 'IDENTIFIED' : 'CODER_NOT_FOUND'
  }
}];

// Simulación / Preparación de despacho de correo para Coder No Identificado
const d = $('06A Preparar Caso No Identificado').first().json;
const inserted = $input.first()?.json || {};

return [{
  json: {
    status: 'SENT',
    recipient: d.sender_email,
    subject: d.reply_subject,
    justification_id: inserted.id || null,
    html: d.reply_body_html,
    dispatched_at: new Date().toISOString()
  }
}];

// 07. Preparar Payload para Strata Core API
const d = $input.first().json;

let fileBase64 = null;
let filename = null;
if (d.attachments && d.attachments.length > 0) {
  fileBase64 = d.attachments[0].data_base64 || null;
  filename = d.attachments[0].filename || 'adjunto.pdf';
}

return [{
  json: {
    ...d,
    strata_request_body: {
      email_subject: d.email_subject,
      email_body: d.email_body,
      model: 'qwen2.5:1.5b',
      file_base64: fileBase64,
      filename: filename
    }
  }
}];

// 09. Validación de Schema, Guardrails y Categorización Asistida para HSE
const httpResult = $input.first()?.json || {};
const previousData = $('07 Preparar Payload Strata Core').first().json;

const hasHttpError = Boolean(httpResult.error || !httpResult.tipo_novedad);

let aiCategoria = 'REVISION_MANUAL';
let aiValido = false;
let aiTipo = 'no_identificado';
let aiFechaAfectada = null;
let aiMotivo = '';
let aiConfidence = 0.0;
let aiRequiereManual = false;
let aiFullResponse = {};

if (hasHttpError) {
  aiCategoria = 'REVISION_MANUAL';
  aiValido = false;
  aiTipo = 'no_identificado';
  aiConfidence = 0.0;
  aiRequiereManual = true;
  aiMotivo = 'Fallo técnico de comunicación o timeout con el motor de IA Strata Core / Ollama. Derivado a revisión manual de la Team Leader de HSE.';
  aiFullResponse = { error: true, details: httpResult.error || 'Connection failure' };
} else {
  aiCategoria = httpResult.categoria_sugerida || (httpResult.requiere_revision_manual ? 'REVISION_MANUAL' : (httpResult.valido ? 'POSIBLEMENTE_VALIDO' : 'POSIBLEMENTE_INVALIDO'));
  aiValido = Boolean(httpResult.valido);
  aiTipo = httpResult.tipo_novedad || 'no_identificado';
  aiFechaAfectada = httpResult.fecha_afectada || null;
  aiMotivo = httpResult.motivo_decision || 'Evaluación asistida generada por Qwen 2.5';
  aiConfidence = typeof httpResult.confianza_score === 'number' ? httpResult.confianza_score : 0.85;
  aiRequiereManual = Boolean(httpResult.requiere_revision_manual);
  aiFullResponse = httpResult;
}

// Fechas: Normalización a start_date y end_date
const todayStr = (previousData.received_at || new Date().toISOString()).split('T')[0];
let startDate = todayStr;
let endDate = todayStr;

if (aiFechaAfectada && /^\d{4}-\d{2}-\d{2}$/.test(aiFechaAfectada)) {
  startDate = aiFechaAfectada;
  endDate = aiFechaAfectada;
}

// Guardrails de Negocio adicionales
const lowerBody = (previousData.email_subject + ' ' + previousData.email_body).toLowerCase();

if (/falleci|luto|funerar|entierro|calamidad/.test(lowerBody)) {
  aiTipo = 'calamidad';
  if (!previousData.has_attachments) {
    aiCategoria = 'REVISION_MANUAL';
    aiValido = false;
    aiRequiereManual = true;
    aiMotivo = 'Reporte de calamidad familiar sin soporte adjunto. Requiere validación manual de la Team Leader de HSE.';
  }
}

if (/descuento|cursos de|promocion|suscripcion/.test(lowerBody)) {
  aiTipo = 'no_identificado';
  aiCategoria = 'REVISION_MANUAL';
  aiValido = false;
  aiRequiereManual = true;
  aiMotivo = 'Contenido sospechoso de spam o promoción comercial.';
}

let validationStatus = aiCategoria;
if (aiRequiereManual || aiConfidence < 0.80) {
  validationStatus = 'REVISION_MANUAL';
  aiCategoria = 'REVISION_MANUAL';
}

return [{
  json: {
    ...previousData,
    intent: aiTipo.toUpperCase(),
    excuse_type: aiTipo,
    start_date: startDate,
    end_date: endDate,
    ai_recommendation: aiCategoria,
    ai_confidence: aiConfidence,
    ai_reason: aiMotivo,
    ai_response: aiFullResponse,
    ai_model: 'qwen2.5:1.5b',
    validation_status: validationStatus,
    resolution_mode: 'AUTOMATIC_AI',
    has_human_intervention: false,
    validation_notes: `Asistencia AI Qwen 2.5: ${aiCategoria}. Confianza: ${aiConfidence}. Requiere auditoría manual: ${aiRequiereManual}.`
  }
}];

// 12A. Acuse de Recibo: Posiblemente Válido (En espera de decisión final de Team Leader HSE)
const d = $('09 Validar Schema y Guardrails').first().json;
const inserted = $input.first()?.json || {};

const html = `<div style="font-family: Arial, sans-serif; color: #2c3e50; line-height: 1.6;">
  <h2 style="color: #27ae60;">Radicado de Justificación — En Revisión</h2>
  <p>Hola <strong>${d.coder_name}</strong>,</p>
  <p>Te confirmamos que tu justificación de inasistencia para la fecha <strong>${d.start_date}</strong> ha sido recibida y radicada exitosamente.</p>
  <div style="background: #f4f9f4; border-left: 4px solid #27ae60; padding: 12px; margin: 15px 0;">
    <p style="margin: 0;"><strong>Tipo de Novedad:</strong> ${d.excuse_type.replace('_', ' ').toUpperCase()}</p>
    <p style="margin: 5px 0 0 0;"><strong>Clasificación Preliminar:</strong> POSIBLEMENTE VÁLIDA (Soporte en orden)</p>
    <p style="margin: 5px 0 0 0;"><strong>Detalle Técnico:</strong> ${d.ai_reason}</p>
    <p style="margin: 5px 0 0 0; font-size: 12px; color: #666;">Radicado ID: ${inserted.id || 'N/A'}</p>
  </div>
  <p>Tu caso se encuentra en la bandeja de la <strong>Team Leader de HSE (Paola)</strong>, quien emitirá la decisión final de aprobación en el sistema institucional.</p>
  <hr style="border: 0; border-top: 1px solid #eee; margin: 20px 0;" />
  <p style="font-size: 12px; color: #7f8c8d;">Área de Habilidades Socioemocionales (HSE) — RIWI</p>
</div>`;

return [{
  json: {
    status: 'PRELIMINARY_VALID_EMAIL_SENT',
    recipient: d.sender_email,
    subject: 'RIWI HSE - Radicado de Justificación [' + d.start_date + ']',
    justification_id: inserted.id,
    html: html
  }
}];

// 12B. Acuse de Recibo con Observaciones: Posiblemente Inválido (Para auditoría de la Team Leader)
const d = $('09 Validar Schema y Guardrails').first().json;
const inserted = $input.first()?.json || {};

const html = `<div style="font-family: Arial, sans-serif; color: #2c3e50; line-height: 1.6;">
  <h2 style="color: #e67e22;">Radicado de Justificación con Observaciones</h2>
  <p>Hola <strong>${d.coder_name}</strong>,</p>
  <p>Hemos recibido tu solicitud de excusa con fecha <strong>${d.start_date}</strong>. En la auditoría preliminar se detectaron observaciones en el soporte suministrado:</p>
  <div style="background: #fef9e7; border-left: 4px solid #e67e22; padding: 12px; margin: 15px 0;">
    <p style="margin: 0;"><strong>Observación Preliminar:</strong> ${d.ai_reason}</p>
    <p style="margin: 5px 0 0 0; font-size: 12px; color: #666;">Radicado ID: ${inserted.id || 'N/A'}</p>
  </div>
  <p>Tu caso ha sido remitido a la <strong>Team Leader de HSE (Paola)</strong> para su revisión y determinación final. En caso de requerirse un documento complementario, el equipo de HSE se comunicará contigo.</p>
  <hr style="border: 0; border-top: 1px solid #eee; margin: 20px 0;" />
  <p style="font-size: 12px; color: #7f8c8d;">Área de Habilidades Socioemocionales (HSE) — RIWI</p>
</div>`;

return [{
  json: {
    status: 'PRELIMINARY_OBSERVATION_EMAIL_SENT',
    recipient: d.sender_email,
    subject: 'RIWI HSE - Radicado con Observaciones [' + d.start_date + ']',
    justification_id: inserted.id,
    html: html
  }
}];

// 12C. Registro en Cola de Pendientes HSE (Listo para consumo en Frontend)
const d = $('09 Validar Schema y Guardrails').first().json;
const inserted = $input.first()?.json || {};

return [{
  json: {
    status: 'QUEUED_FOR_HSE_REVIEW',
    justification_id: inserted.id,
    coder_name: d.coder_name,
    sender_email: d.sender_email,
    category: 'REVISION_MANUAL',
    reason: d.ai_reason,
    email_url: d.email_url,
    queued_at: new Date().toISOString()
  }
}];

// 14. Generar y despachar notificación al Coder tras intervención manual de HSE
const body = $input.first()?.json?.body || $input.first()?.json || {};

const action = body.action || 'APPROVED';
const coderName = body.coder_name || 'Coder';
const recipientEmail = body.recipient_email || body.sender_email;
const startDate = body.start_date || 'la fecha solicitada';
const hseNotes = body.hse_notes || 'Revisado por el equipo de HSE.';
const reviewerName = body.hse_reviewer_name || 'Equipo de Acompañamiento HSE';

let subject = `RIWI HSE - Resolución de tu Justificación [${startDate}]`;
let message = '';
let color = '#27ae60';

if (action === 'APPROVED') {
  color = '#27ae60';
  message = `<p>El equipo de Habilidades Socioemocionales ha revisado tu caso y ha <strong style="color: #27ae60;">APROBADO</strong> tu justificación.</p>
  <div style="background: #f4f9f4; border-left: 4px solid #27ae60; padding: 12px; margin: 15px 0;">
    <p style="margin: 0;"><strong>Observaciones del analista:</strong> ${hseNotes}</p>
    <p style="margin: 5px 0 0 0; font-size: 12px; color: #666;">Revisado por: ${reviewerName}</p>
  </div>`;
} else if (action === 'DISAPPROVED') {
  color = '#e74c3c';
  message = `<p>El equipo de Habilidades Socioemocionales ha revisado tu solicitud y ha determinado que <strong style="color: #e74c3c;">NO CUMPLE</strong> con los criterios de aprobación.</p>
  <div style="background: #fdf3f2; border-left: 4px solid #e74c3c; padding: 12px; margin: 15px 0;">
    <p style="margin: 0;"><strong>Motivo de rechazo:</strong> ${hseNotes}</p>
    <p style="margin: 5px 0 0 0; font-size: 12px; color: #666;">Revisado por: ${reviewerName}</p>
  </div>`;
} else {
  // REQUEST_CORRECTION
  color = '#f39c12';
  subject = `RIWI HSE - Información requerida sobre tu excusa [${startDate}]`;
  message = `<p>El equipo de Habilidades Socioemocionales requiere información o soportes adicionales para resolver tu solicitud.</p>
  <div style="background: #fef9e7; border-left: 4px solid #f39c12; padding: 12px; margin: 15px 0;">
    <p style="margin: 0;"><strong>Requerimiento:</strong> ${hseNotes}</p>
    <p style="margin: 5px 0 0 0; font-size: 12px; color: #666;">Por favor responde a este correo adjuntando el soporte solicitado.</p>
  </div>`;
}

const html = `<div style="font-family: Arial, sans-serif; color: #2c3e50; line-height: 1.6;">
  <h2 style="color: ${color};">Actualización de tu Justificación</h2>
  <p>Hola <strong>${coderName}</strong>,</p>
  ${message}
  <hr style="border: 0; border-top: 1px solid #eee; margin: 20px 0;" />
  <p style="font-size: 12px; color: #7f8c8d;">Área de Habilidades Socioemocionales (HSE) — RIWI</p>
</div>`;

return [{
  json: {
    status: 'HSE_NOTIFICATION_DISPATCHED',
    action: action,
    recipient: recipientEmail,
    subject: subject,
    justification_id: body.justification_id || null,
    html: html,
    dispatched_at: new Date().toISOString()
  }
}];
